"""Explain wake variants, scheduling hints and poll event keys."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1465': ('같은 안내 방송도 누구를 부를지, 특별권 몇 장을 처리할지, 명단을 누가 잠글지를 정해야 합니다. 이름이 비슷한 함수들도 이 세 설정이 다릅니다.', '깨우기 API의 상태 필터·한도·잠금 책임을 구별합니다.', 'wake_up: NORMAL·1·내부 잠금, interruptible: INTERRUPTIBLE·1·내부 잠금, locked: NORMAL·1·호출자 잠금을 세 줄로 적으세요.', ['대기 상태는 태스크가 어떤 방식으로 기다리는지 나타내는 표시입니다. 깨우기 함수의 mode는 어떤 대기 상태를 대상으로 할지 전달하는 필터입니다. 기본 깨우기 경로는 이 필터와 태스크 상태를 맞춰 봅니다.', 'wake_up은 TASK_NORMAL을 전달합니다. 이 값은 일반적으로 깨우는 대기 상태들의 묶음이며, 모든 특수 상태를 무조건 깨운다는 뜻은 아닙니다. wake_up_interruptible은 TASK_INTERRUPTIBLE을 전달해 신호로 중단 가능한 대기 상태를 대상으로 합니다.', '기본 wake_up의 exclusive 한도는 1입니다. wake_up_nr는 호출자가 준 nr를 한도로 전달합니다. wake_up_all은 0을 전달해 양수 한도로 멈추는 방식을 사용하지 않습니다. 일반 항목도 처리될 수 있으므로 한도 1이 전체 태스크 딱 한 명이라는 뜻은 아닙니다.', '일반 __wake_up 경로는 공통 잠금 함수를 이용합니다. 반면 wake_up_locked는 호출자가 대기열 head 잠금을 이미 잡고 있어야 합니다. 그 상태에서 내부 순회로 들어가므로 함수 안에서 같은 잠금을 다시 잡지 않습니다.', '이미 같은 대기열 잠금을 잡았는데 잠금을 다시 획득하는 일반 API를 부르면 문제가 될 수 있습니다. 반대로 잠금 없이 locked 함수를 부르면 목록 보호의 전제가 깨집니다. 함수 이름만 골라 쓰지 말고 현재 누가 잠금을 잡았는지 확인해야 합니다.', '실제 코드에서는 기다릴 때의 state, 깨울 때의 mode, exclusive 한도, 잠금 책임을 나란히 적어 보세요. 사용자 콜백이 있으면 전달된 mode와 결과를 어떻게 해석하는지도 확인합니다. 조회나 깨우기 호출만으로 실제 자원을 얻는 것은 아닙니다.'], [('wake_up_interruptible이 전달하는 상태 필터는?', ['항상 TASK_NORMAL 전체예요', 'TASK_INTERRUPTIBLE이에요'], '헤더 매크로의 두 번째 인자가 TASK_INTERRUPTIBLE입니다. 이름이 비슷한 wake_up은 TASK_NORMAL을 전달하므로 두 인자를 구별해야 합니다.'), ('wake_up_locked는 호출자가 대기열 잠금을 이미 잡아야 할까요?', ['네. 호출자의 잠금이 필요한 변형이에요', '아니요. 언제나 함수가 새로 잠가요'], 'locked 경로는 이미 잠금이 잡힌 상황에서 내부 순회를 호출합니다. 일반 잠금 포함 경로와 책임이 다르므로 잠금 없이 호출해도 된다는 답은 틀립니다.')]), 'os1466': ('내가 곧 자리를 비울 테니 다음 사람이 일할 준비를 하라고 알려 줍니다. 이 알림은 다음 사람의 일을 끝까지 대신 기다리는 약속이 아닙니다.', 'sync 깨우기의 스케줄링 힌트와 상대 작업 완료 대기를 구별합니다.', '깨우는 쪽이 곧 실행을 양보할 예정 → WF_SYNC 전달 → 상대 깨우기 시도 → 함수 반환을 그리세요. 상대 작업 완료는 별도 사건이라고 적으세요.', ['__wake_up_sync_key의 sync는 여기서 깨우는 쪽이 곧 schedule로 실행 기회를 양보할 상황과 연결됩니다. 스케줄러는 어느 작업을 어느 CPU에서 실행할지 정하는 커널의 담당 부분입니다.', '함수는 WF_SYNC라는 표시를 공통 깨우기 코드에 전달합니다. 원문은 불필요한 CPU 사이 이동이나 CPU가 하나일 때의 추가 선점을 줄이려는 목적을 설명합니다. 선점은 실행 중인 작업을 멈추고 다른 작업에 기회를 주는 일입니다.', '이것은 상대 작업이 모든 일을 끝내거나 종료할 때까지 기다리는 join 같은 동작이 아닙니다. 호출자는 깨우기를 요청하고 돌아올 수 있으며, 상대의 실제 작업 완료는 나중일 수 있습니다. sync라는 단어만으로 완료 보장을 추측하면 안 됩니다.', '이 함수는 맨 앞에서 wq_head가 NULL인지 검사합니다. NULL은 대기열 주소가 없다는 뜻입니다. 없으면 바로 return하고, 있으면 __wake_up_common_lock에 mode, 한도 1, WF_SYNC, key를 전달합니다.', 'key는 깨우기 콜백에 넘기는 추가 정보입니다. 이 함수는 key의 내용을 직접 해석하지 않습니다. __wake_up_sync는 이 함수에 key=NULL을 주는 형태이고, locked_sync_key는 호출자가 이미 대기열 잠금을 잡은 경로입니다.', '이 함수가 NULL head를 검사한다고 모든 wake 함수도 NULL을 허용한다고 생각하면 안 됩니다. 또한 WF_SYNC 전달이 모든 사용자 콜백과 실행 환경에서 동일한 CPU 배치 결과를 보장하는 것은 아닙니다. 실제 효과는 콜백과 스케줄러의 후속 처리를 함께 봐야 합니다.'], [('sync 깨우기는 상대 태스크가 일을 마칠 때까지 기다릴까요?', ['네. 상대가 종료한 뒤에만 돌아와요', '아니요. WF_SYNC 힌트를 전달하는 깨우기예요'], '곧 실행을 양보할 상황을 스케줄링에 알리는 것이 목적입니다. 상대 작업 완료를 기다리는 코드가 아니므로 sync라는 이름을 완료 대기로 해석하면 틀립니다.'), ('__wake_up_sync_key의 head가 NULL이면 어떻게 할까요?', ['검사하고 바로 반환해요', '반드시 NULL의 잠금에 접근해요'], '함수 맨 앞에 !wq_head이면 return하는 분기가 있습니다. 이 함수의 확인된 계약이며 다른 깨우기 API까지 모두 같은 계약이라고 넓혀 해석해서는 안 됩니다.')]), 'os1467': ('담당자에게 “현재 작업실에서 처리하는 방향으로 부탁합니다”라는 표시를 전달할 수 있습니다. 표시를 전달하는 창구와 실제 배치를 결정하는 담당자는 서로 다른 단계입니다.', 'WF_CURRENT_CPU 전달과 실제 CPU 선택을 구별합니다.', '__wake_up_on_current_cpu → 공통 잠금 함수 → 항목 콜백 → 후속 스케줄러 처리를 그리세요. 첫 화살표 위에 한도 1·WF_CURRENT_CPU·key를 적으세요.', ['__wake_up_on_current_cpu의 본문은 공통 깨우기 함수 호출 하나입니다. 대기열 주소와 mode, exclusive 한도 1, WF_CURRENT_CPU 표시, key를 넘깁니다. current CPU는 현재 이 코드를 실행하는 CPU를 뜻합니다.', 'WF_CURRENT_CPU는 깨우기 처리에 전달하는 표시입니다. 같은 자리에 sync 변형은 WF_SYNC를 전달합니다. 두 함수의 이름이 비슷해도 넘기는 표시가 다르므로 코드의 인자를 확인해야 합니다.', '공통 함수는 대기열 잠금을 잡고 항목의 콜백을 호출합니다. 콜백이 받은 wake_flags를 이용해 다음 처리로 전달할 수 있습니다. 기본 깨우기 경로에서는 스케줄러가 실제 태스크 실행 준비와 CPU 선택을 처리합니다.', '이 작은 helper 안에 태스크의 CPU 번호를 직접 바꾸거나 CPU마다 새 대기열을 만드는 코드는 없습니다. 한 대기열의 모든 항목을 현재 CPU 전용 목록으로 옮기는 함수라고 읽으면 틀립니다.', '사용자 콜백은 flags를 어떻게 처리할지 자신의 약속을 가집니다. 따라서 이 helper 호출만 보고 어떤 콜백이든 반드시 현재 CPU에서 태스크를 실행시킨다고 보장할 수 없습니다. 표시 전달과 실제 실행 결과를 구별하세요.', '잠금과 한도는 공통 깨우기 규칙을 그대로 따릅니다. 한도 1은 전체 콜백 한 번만 호출한다는 뜻이 아니고, 함수가 돌아왔다고 상대 작업이 즉시 실행됐거나 완료됐다는 뜻도 아닙니다. 실제 흐름을 알려면 뒤의 콜백과 스케줄링 경로를 연결합니다.'], [('이 helper가 전달하는 wake flag는?', ['언제나 WF_SYNC만 전달해요', 'WF_CURRENT_CPU를 전달해요'], '공통 호출의 네 번째 인자는 WF_CURRENT_CPU입니다. WF_SYNC는 별도의 sync 경로에 쓰이므로 서로 바꾸어 읽으면 안 됩니다.'), ('이 helper 자체가 모든 사용자 콜백의 태스크 CPU 배치를 직접 수행할까요?', ['아니요. 플래그를 전달하고 후속 처리로 이어져요', '네. 콜백과 무관하게 직접 CPU를 바꿔요'], '본문은 공통 함수 호출입니다. 콜백의 플래그 해석과 스케줄러의 선택이 뒤따르는 별도 단계이므로 모든 결과를 이 한 함수가 직접 강제한다는 답은 틀립니다.')]), 'os1468': ('봉투에 집 주소 대신 약속한 사건 번호를 넣어 보냈다고 합시다. 봉투 모양이 같아도 그 번호를 실제 집 주소로 찾아가면 안 됩니다.', 'poll의 사건 비트를 포인터 모양의 key로 전달하는 약속을 이해합니다.', '연습용 사건 비트 001과 100을 합쳐 101 → poll_to_key → key_to_poll → 101을 적으세요. 이 번호들은 설명용이며 실제 poll 상수 이름과 값은 별도로 확인합니다.', ['poll은 파일이나 장치에 읽을 자료가 있는지 같은 준비 상태를 살피는 인터페이스입니다. 여러 사건을 비트 마스크로 표현할 수 있습니다. 비트는 0 또는 1 한 칸이고, 마스크는 각 칸에 특정 사건의 여부를 담는 값입니다.', 'poll_to_key는 사건 마스크를 __poll_t와 uintptr_t를 거쳐 void * 모양으로 전달합니다. __poll_t는 poll 사건 값의 형식이고 uintptr_t는 포인터를 표현할 폭의 부호 없는 정수 형식입니다. 여기의 형식 변환은 사건 번호를 콜백의 key 인자에 맞춰 싣는 약속입니다.', '포인터 모양이라고 실제 객체가 그 주소에 놓여 있다는 뜻은 아닙니다. 이 key를 struct file 주소라고 가정하거나 *key처럼 메모리를 따라가 읽으면 안 됩니다. 사건 마스크로 해석해야 하는 값입니다.', 'key_to_poll은 전달된 key를 다시 사건 마스크로 해석합니다. __force 표기는 커널의 형식 검사 도구에 의도한 변환임을 나타내는 표기이며, 주소에 실제 객체를 새로 만드는 연산이 아닙니다.', '항목의 private와 이번 호출의 key는 역할이 다릅니다. private는 항목에 저장한 콜백 문맥이고 key는 깨우기 호출마다 전달하는 사건 정보입니다. 둘 다 항상 current이거나 둘 다 태스크 주소라고 생각하면 안 됩니다.', 'wake_up_poll은 TASK_NORMAL, 한도 1, 변환한 key를 전달합니다. interruptible_poll은 상태 필터를 바꾸고, sync_poll은 sync 표시 경로로, locked_poll은 호출자 잠금 경로로 갑니다. 사건 정보뿐 아니라 상태·한도·잠금 조건도 맞춰 사용해야 합니다.'], [('poll_to_key의 결과를 일반 객체 주소처럼 따라가 읽어야 할까요?', ['네. 반드시 struct file이 놓인 주소예요', '아니요. 사건 비트를 전달하는 표현이에요'], '이 변환은 마스크 값을 key 인자에 실어 보냅니다. 실제 객체를 할당하거나 그 주소를 찾은 것이 아니므로 일반 객체처럼 역참조하면 안 됩니다.'), ('poll 깨우기의 key와 대기 항목의 private는 같은 역할일까요?', ['아니요. 이번 사건 정보와 항목의 콜백 문맥으로 구별해요', '네. 둘 다 항상 current를 담아요'], 'private는 항목에 저장되고 key는 깨우기 요청에 따라 전달됩니다. 각각 콜백 약속에 맞게 해석하므로 둘 다 현재 태스크라고 읽는 답은 틀립니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_362.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
